const input = $input.first()?.json;
const payload = input?.json;
const doers = payload?.doers;

if (!Array.isArray(doers) || doers.length === 0) {
  throw new Error('Estate Summary payload has no doers');
}

const dates = new Set();
for (const [index, doer] of doers.entries()) {
  const reportDate = doer?.Date;
  if (typeof reportDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(reportDate)) {
    throw new Error('Estate Summary doer ' + (index + 1) + ' has an invalid ISO Date');
  }
  const parsed = new Date(reportDate + 'T00:00:00Z');
  if (Number.isNaN(parsed.valueOf()) || parsed.toISOString().slice(0, 10) !== reportDate) {
    throw new Error('Estate Summary doer ' + (index + 1) + ' has an invalid calendar Date');
  }
  if (typeof doer.Label !== 'string' || doer.Label.trim() === '') {
    throw new Error('Estate Summary doer ' + (index + 1) + ' has no mapped Label');
  }
  dates.add(reportDate);
}

if (dates.size !== 1) {
  throw new Error('Estate Summary payload contains mixed report dates');
}

return $input.all();

const row = $input.first()?.json;
const executionId = String($execution.id);
const lockAcquired = row?.locked === true && String(row?.token ?? '') === executionId;
return [{
  json: {
    lockAcquired,
    status: 409,
    body: lockAcquired ? null : {
      error: {
        code: 'ESTATE_SUMMARY_BUSY',
        message: 'Estate Summary generation is already in progress. Wait for it to finish before retrying.',
      },
      execution_id: executionId,
    },
  },
}];

const doers = $('Validate Estate Payload').first().json?.json?.doers;
if (!Array.isArray(doers) || doers.length === 0) throw new Error('Validated Estate payload is unavailable');

const reportDate = doers[0].Date;
const existingValues = $input.first().json?.values ?? [];

function normalizeDate(value) {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return new Date(Math.round((value - 25569) * 86400000)).toISOString().slice(0, 10);
  }
  if (typeof value !== 'string' || value.trim() === '') return null;
  const text = value.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
  const parsed = new Date(text + ' UTC');
  return Number.isNaN(parsed.valueOf()) ? null : parsed.toISOString().slice(0, 10);
}

function text(value) {
  const normalized = value === null || value === undefined ? '' : String(value).trim();
  return /^'[=+\-@]/.test(normalized) ? normalized.slice(1) : normalized;
}

function payloadKey(doer) {
  return [
    reportDate,
    text(doer.Name),
    text(doer.Category),
    text(doer['Matching Status']),
    text(doer.Section),
    text(doer.Label),
  ].join('\u001f');
}

function rawKey(row) {
  return [normalizeDate(row[0]), ...row.slice(1, 6).map(text)].join('\u001f');
}

function counts(keys) {
  const result = new Map();
  for (const key of keys) result.set(key, (result.get(key) ?? 0) + 1);
  return result;
}

const existingWeekRows = existingValues.slice(1).filter((row) => normalizeDate(row?.[0]) === reportDate);
if (existingWeekRows.length > 0) {
  const expected = counts(doers.map(payloadKey));
  const actual = counts(existingWeekRows.map(rawKey));
  const identical = expected.size === actual.size
    && [...expected].every(([key, count]) => actual.get(key) === count);
  if (!identical) {
    throw new Error('Raw already contains a conflicting Estate batch for ' + reportDate);
  }
}

return [{
  json: {
    rows: doers,
    reportDate,
    rowsWritten: doers.length,
    shouldAppend: existingWeekRows.length === 0,
    reusedExistingBatch: existingWeekRows.length > 0,
  },
}];

const plan = $input.first().json;
return plan.rows.map((doer) => ({
  json: {
    Week: doer.Date,
    Doer: doer.Name,
    Category: doer.Category,
    'Matching Status': doer['Matching Status'],
    Section: doer.Section,
    Label: doer.Label,
  },
}));

const rows = $input.all().map((item) => item.json);
if (rows.length === 0) throw new Error('No Raw rows were written');

const validatedDoers = $('Validate Estate Payload').first().json?.json?.doers ?? [];
if (rows.length !== validatedDoers.length) {
  throw new Error('Raw row count does not match the validated Estate payload');
}

const dates = new Set(rows.map((row) => row.Week));
if (dates.size !== 1) throw new Error('Appended Raw rows contain mixed report dates');
const reportDate = [...dates][0];
if (typeof reportDate !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(reportDate)) {
  throw new Error('Appended Raw rows contain an invalid report date');
}

return [{
  json: {
    reportDate,
    rowsWritten: rows.length,
  },
}];

const context = $('Prepare Summary Update').first().json;
const grid = $('Read Summary Grid').first().json;
const downstreamGrid = $input.first().json;
const SUMMARY_SHEET_ID = 1820943754;
const DOWNSTREAM_SHEET_ID = 1141614680;
const MIN_REPORT_COLUMN = 1;
const MAX_TEMPLATE_LOOKBACK = 12;
const REQUIRED_FORMULA_ROWS = [3, 4, 5, 6, 12, 15, 17, 64];

const sourceSheet = grid?.sheets?.find((sheet) => sheet?.properties?.sheetId === SUMMARY_SHEET_ID);
const downstreamSheet = downstreamGrid?.sheets?.find((sheet) => sheet?.properties?.sheetId === DOWNSTREAM_SHEET_ID);
if (sourceSheet?.properties?.title !== 'Summary') {
  throw new Error('Source Summary sheet ID/title pairing is invalid');
}
if (downstreamSheet?.properties?.title !== '2026 Weekly Doer Estate') {
  throw new Error('Downstream Estate sheet ID/title pairing is invalid');
}
const rowData = sourceSheet?.data?.[0]?.rowData ?? [];

function cellAt(rowNumber, columnIndex) {
  return rowData[rowNumber - 1]?.values?.[columnIndex] ?? {};
}

function isoFromCell(cell) {
  const serial = cell?.effectiveValue?.numberValue ?? cell?.userEnteredValue?.numberValue;
  if (Number.isFinite(serial)) {
    return new Date(Math.round((serial - 25569) * 86400000)).toISOString().slice(0, 10);
  }
  const text = cell?.formattedValue ?? cell?.userEnteredValue?.stringValue;
  if (typeof text !== 'string' || text.trim() === '') return null;
  const trimmed = text.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return trimmed;
  const parsed = new Date(trimmed + ' UTC');
  return Number.isNaN(parsed.valueOf()) ? null : parsed.toISOString().slice(0, 10);
}

function effectiveNumber(rowNumber, columnIndex) {
  const value = cellAt(rowNumber, columnIndex)?.effectiveValue?.numberValue;
  return Number.isFinite(value) ? value : null;
}

function hasFormula(rowNumber, columnIndex) {
  const formula = cellAt(rowNumber, columnIndex)?.userEnteredValue?.formulaValue;
  return typeof formula === 'string' && formula.startsWith('=');
}

function hasUserValue(rowNumber, columnIndex) {
  const cell = cellAt(rowNumber, columnIndex);
  return Boolean(cell?.userEnteredValue && Object.keys(cell.userEnteredValue).length > 0);
}

function columnLetter(zeroBasedIndex) {
  let number = zeroBasedIndex + 1;
  let result = '';
  while (number > 0) {
    number -= 1;
    result = String.fromCharCode(65 + (number % 26)) + result;
    number = Math.floor(number / 26);
  }
  return result;
}

const headerCells = rowData[0]?.values ?? [];
let existingColumn = null;
let lastReportColumn = null;
for (let column = MIN_REPORT_COLUMN; column < headerCells.length; column += 1) {
  const isoDate = isoFromCell(headerCells[column]);
  if (!isoDate) continue;
  lastReportColumn = column;
  if (isoDate === context.reportDate) existingColumn = column;
}

if (lastReportColumn === null) throw new Error('Summary has no report-date columns');
const targetColumn = existingColumn ?? lastReportColumn + 1;
if (existingColumn === null && Array.from({ length: 66 }, (_, index) => index + 1).some((row) => hasUserValue(row, targetColumn))) {
  throw new Error('The next Summary report column is not blank');
}

const downstreamColumn = targetColumn + 12;
const downstreamColumnCount = downstreamSheet?.properties?.gridProperties?.columnCount;
const sourceColumnCount = sourceSheet?.properties?.gridProperties?.columnCount;
if (!Number.isInteger(sourceColumnCount)) {
  throw new Error('Could not read the source Summary sheet column count');
}
if (!Number.isInteger(downstreamColumnCount)) {
  throw new Error('Could not read the downstream Estate sheet column count');
}

function buildResult({ templateColumn, requiredFormulaRows, requests, formulaRepairs, shouldApplySummaryUpdate }) {
  const sourceColumnsToAppend = Math.max(0, targetColumn + 1 - sourceColumnCount);
  const downstreamColumnsToAppend = Math.max(0, downstreamColumn + 1 - downstreamColumnCount);
  return [{
    json: {
      ...context,
      targetColumnLetter: columnLetter(targetColumn),
      downstreamColumnLetter: columnLetter(downstreamColumn),
      targetWasExisting: existingColumn !== null,
      templateColumnLetter: templateColumn === null ? null : columnLetter(templateColumn),
      formulaRepairs,
      shouldApplySummaryUpdate,
      batchUpdateBody: { requests },
      downstreamCapacityBody: {
        requests: [{
          appendDimension: {
            sheetId: DOWNSTREAM_SHEET_ID,
            dimension: 'COLUMNS',
            length: downstreamColumnsToAppend,
          },
        }],
      },
      downstreamColumnsToAppend,
      sourceCapacityBody: {
        requests: [{
          appendDimension: {
            sheetId: SUMMARY_SHEET_ID,
            dimension: 'COLUMNS',
            length: sourceColumnsToAppend,
          },
        }],
      },
      sourceColumnsToAppend,
      requiredFormulaRows,
    },
  }];
}

if (existingColumn !== null) {
  const existingFormulaRows = [];
  for (let row = 3; row <= 66; row += 1) {
    if (hasFormula(row, existingColumn)) existingFormulaRows.push(row);
  }
  const formulasAreValid = REQUIRED_FORMULA_ROWS.every((row) => hasFormula(row, existingColumn));
  const doers = effectiveNumber(3, existingColumn);
  const billed = effectiveNumber(4, existingColumn);
  const unbilled = effectiveNumber(15, existingColumn);
  const totalsAreValid = doers !== null
    && billed !== null
    && unbilled !== null
    && doers === billed + unbilled;
  if (formulasAreValid && totalsAreValid) {
    return buildResult({
      templateColumn: null,
      requiredFormulaRows: existingFormulaRows,
      requests: [],
      formulaRepairs: 0,
      shouldApplySummaryUpdate: false,
    });
  }
}

let templateColumn = null;
const templateStart = Math.min(targetColumn - 1, lastReportColumn);
const templateEnd = Math.max(MIN_REPORT_COLUMN, templateStart - MAX_TEMPLATE_LOOKBACK + 1);
for (let column = templateStart; column >= templateEnd; column -= 1) {
  const formulasAreValid = REQUIRED_FORMULA_ROWS.every((row) => hasFormula(row, column));
  const doers = effectiveNumber(3, column);
  const billed = effectiveNumber(4, column);
  const unbilled = effectiveNumber(15, column);
  if (
    formulasAreValid
    && doers !== null
    && billed !== null
    && unbilled !== null
    && doers === billed + unbilled
  ) {
    templateColumn = column;
    break;
  }
}
if (templateColumn === null) throw new Error('No valid Summary formula template column was found');

const requiredFormulaRows = [];
for (let row = 3; row <= 66; row += 1) {
  if (hasFormula(row, templateColumn)) requiredFormulaRows.push(row);
}

const serial = (Date.parse(context.reportDate + 'T00:00:00Z') / 86400000) + 25569;
const requests = [{
  updateCells: {
    range: {
      sheetId: SUMMARY_SHEET_ID,
      startRowIndex: 0,
      endRowIndex: 1,
      startColumnIndex: targetColumn,
      endColumnIndex: targetColumn + 1,
    },
    rows: [{
      values: [{
        userEnteredValue: { numberValue: serial },
        userEnteredFormat: { numberFormat: { type: 'DATE', pattern: 'd-mmm-yyyy' } },
      }],
    }],
    fields: 'userEnteredValue,userEnteredFormat.numberFormat',
  },
}];

if (existingColumn === null) {
  requests.push({
    copyPaste: {
      source: {
        sheetId: SUMMARY_SHEET_ID,
        startRowIndex: 2,
        endRowIndex: 66,
        startColumnIndex: templateColumn,
        endColumnIndex: templateColumn + 1,
      },
      destination: {
        sheetId: SUMMARY_SHEET_ID,
        startRowIndex: 2,
        endRowIndex: 66,
        startColumnIndex: targetColumn,
        endColumnIndex: targetColumn + 1,
      },
      pasteType: 'PASTE_FORMULA',
      pasteOrientation: 'NORMAL',
    },
  });
} else {
  for (const row of requiredFormulaRows) {
    requests.push({
      copyPaste: {
        source: {
          sheetId: SUMMARY_SHEET_ID,
          startRowIndex: row - 1,
          endRowIndex: row,
          startColumnIndex: templateColumn,
          endColumnIndex: templateColumn + 1,
        },
        destination: {
          sheetId: SUMMARY_SHEET_ID,
          startRowIndex: row - 1,
          endRowIndex: row,
          startColumnIndex: targetColumn,
          endColumnIndex: targetColumn + 1,
        },
        pasteType: 'PASTE_FORMULA',
        pasteOrientation: 'NORMAL',
      },
    });
  }
}

return buildResult({
  templateColumn,
  requiredFormulaRows,
  requests,
  formulaRepairs: requests.length - 1,
  shouldApplySummaryUpdate: true,
});

const context = $('Build Summary Update').first().json;
const sourceValues = $('Read Source Results').first().json?.values ?? [];
const sourceFormulaValues = $('Read Source Formulas').first().json?.values ?? [];
const downstreamValues = $('Read Downstream Results').first().json?.values ?? [];

function normalizeDate(value) {
  if (typeof value === 'number' && Number.isFinite(value)) {
    return new Date(Math.round((value - 25569) * 86400000)).toISOString().slice(0, 10);
  }
  if (typeof value !== 'string' || value.trim() === '') return null;
  const text = value.trim();
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) return text;
  const parsed = new Date(text + ' UTC');
  return Number.isNaN(parsed.valueOf()) ? null : parsed.toISOString().slice(0, 10);
}

function numberAt(values, rowNumber, startingRow) {
  const raw = values[rowNumber - startingRow]?.[0];
  if (typeof raw === 'number' && Number.isFinite(raw)) return raw;
  if (typeof raw === 'string' && raw.trim() !== '') {
    const parsed = Number(raw.replace(/,/g, ''));
    if (Number.isFinite(parsed)) return parsed;
  }
  return null;
}

function valueAt(values, rowNumber, startingRow) {
  const value = values[rowNumber - startingRow]?.[0];
  if (value === null || value === undefined || value === '') return null;
  return typeof value === 'string' ? value.trim() : value;
}

function assertNoSheetErrors(values, name) {
  for (const row of values) {
    for (const value of row) {
      if (typeof value === 'string' && /^#(?:REF!|N\/A|VALUE!|ERROR!|NAME\?|DIV\/0!|NUM!|NULL!|GETTING_DATA)/i.test(value)) {
        throw new Error(name + ' contains spreadsheet error ' + value);
      }
    }
  }
}

assertNoSheetErrors(sourceValues, 'Source Summary');
assertNoSheetErrors(downstreamValues, 'Downstream Estate workbook');

const source = {
  date: normalizeDate(sourceValues[0]?.[0]),
  doers: numberAt(sourceValues, 3, 1),
  billed: numberAt(sourceValues, 4, 1),
  unbilled: numberAt(sourceValues, 15, 1),
};
const downstream = {
  date: normalizeDate(downstreamValues[0]?.[0]),
  doers: numberAt(downstreamValues, 5, 3),
  billed: numberAt(downstreamValues, 6, 3),
  unbilled: numberAt(downstreamValues, 17, 3),
};

for (const [name, result] of [['Source Summary', source], ['Downstream Estate workbook', downstream]]) {
  if (result.date !== context.reportDate) {
    throw new Error(name + ' did not expose report date ' + context.reportDate);
  }
  if (![result.doers, result.billed, result.unbilled].every(Number.isFinite)) {
    throw new Error(name + ' headline totals are not ready');
  }
  if (result.doers !== result.billed + result.unbilled) {
    throw new Error(name + ' totals are internally inconsistent');
  }
}

if (
  source.doers !== downstream.doers
  || source.billed !== downstream.billed
  || source.unbilled !== downstream.unbilled
) {
  throw new Error('Downstream Estate workbook totals do not match Source Summary');
}

for (const row of context.requiredFormulaRows ?? []) {
  const formula = sourceFormulaValues[row - 1]?.[0];
  if (typeof formula !== 'string' || !formula.startsWith('=')) {
    throw new Error('Source Summary formula row ' + row + ' does not contain a formula');
  }
  const sourceValue = valueAt(sourceValues, row, 1);
  const downstreamValue = valueAt(downstreamValues, row + 2, 3);
  if (JSON.stringify(sourceValue) !== JSON.stringify(downstreamValue)) {
    throw new Error('Downstream Estate workbook differs from Source Summary at formula row ' + row);
  }
}

return [{
  json: {
    rows_written: context.rowsWritten,
    updated_range: 'Raw!A:F',
    source_range: 'Summary!' + context.targetColumnLetter + '1:' + context.targetColumnLetter + '66',
    downstream_range: "'2026 Weekly Doer Estate'!" + context.downstreamColumnLetter + '3:' + context.downstreamColumnLetter + '68',
    totals: source,
    target_was_existing: context.targetWasExisting,
    formula_repairs: context.formulaRepairs,
    formula_rows_verified: (context.requiredFormulaRows ?? []).length,
  },
}];

const row = $input.first()?.json;
if (row?.locked !== false) {
  throw new Error('Estate Summary result was verified, but its execution lock was not released');
}
return [{ json: $('Verify Estate Summary').first().json }];

const input = $input.first()?.json ?? {};
const rawError = input.error && typeof input.error === 'object' ? input.error : input;
const rawMessage = typeof input.error === 'string'
  ? input.error
  : typeof rawError.message === 'string'
    ? rawError.message
    : typeof input.message === 'string'
      ? input.message
      : 'Unknown workflow failure';
const normalizedMessage = rawMessage.replace(/[\r\n\t]+/g, ' ').trim().slice(0, 180);
const conflict = normalizedMessage.startsWith('Raw already contains a conflicting Estate batch');
return [{
  json: {
    status: conflict ? 409 : 500,
    body: {
      error: {
        code: conflict ? 'ESTATE_SUMMARY_CONFLICT' : 'ESTATE_SUMMARY_WORKFLOW_FAILED',
        message: conflict
          ? 'An Estate Summary already exists for this date with different data. Investigate it before retrying.'
          : 'Estate Summary workflow failed' + (normalizedMessage ? ': ' + normalizedMessage : ''),
      },
      execution_id: String($execution.id),
    },
  },
}];

const input = $input.first()?.json ?? {};
const rawError = input.error && typeof input.error === 'object' ? input.error : input;
const rawMessage = typeof rawError.message === 'string' ? rawError.message : 'Invalid Estate Summary request';
const safeMessage = rawMessage.replace(/[\r\n\t]+/g, ' ').trim().slice(0, 180);
return [{
  json: {
    status: 422,
    body: {
      error: {
        code: 'ESTATE_SUMMARY_INVALID_PAYLOAD',
        message: safeMessage || 'Invalid Estate Summary request',
      },
      execution_id: String($execution.id),
    },
  },
}];
